function split_words(txt: string): string[] | number {
    if (txt.includes(' ')) {
        return txt.split(' ');
    } else if (txt.includes(',')) {
        return txt.replace(',', ' ').split(' ');
    } else {
        const count = Array.from(txt).reduce((acc, char) => {
            if (char >= 'a' && char <= 'z' && char.charCodeAt(0) % 2 === 0) {
                acc++;
            }
            return acc;
        }, 0);
        return count;
    }
}

function even_odd_palindrome(n: number): [number, number] {
    function is_palindrome(num: number): boolean {
        return num.toString() === num.toString().split('').reverse().join('');
    }

    let even_palindrome_count = 0;
    let odd_palindrome_count = 0;

    for (let i = 1; i <= n; i++) {
        if (i % 2 === 1 && is_palindrome(i)) {
            odd_palindrome_count++;
        } else if (i % 2 === 0 && is_palindrome(i)) {
            even_palindrome_count++;
        }
    }

    return [even_palindrome_count, odd_palindrome_count];
}

function correct_bracketing(brackets: string): boolean {
    let depth = 0;
    for (const b of brackets) {
        if (b === '(') {
            depth += 1;
        } else {
            depth -= 1;
        }
        if (depth < 0) {
            return false;
        }
    }
    return depth === 0;
}

function largest_prime_factor(n: number): number {
    function is_prime(k: number): boolean {
        if (k < 2) {
            return false;
        }
        for (let i = 2; i < k - 1; i++) {
            if (k % i === 0) {
                return false;
            }
        }
        return true;
    }

    let largest = 1;
    for (let j = 2; j <= n; j++) {
        if (n % j === 0 && is_prime(j)) {
            largest = Math.max(largest, j);
        }
    }
    return largest;
}

