function digits(n: number): number {
    let product = 1;
    let oddCount = 0;
    for (const digit of n.toString()) {
        const intDigit = parseInt(digit, 10);
        if (intDigit % 2 === 1) {
            product *= intDigit;
            oddCount += 1;
        }
    }
    return oddCount === 0 ? 0 : product;
}

