function sort_even(l: number[]): number[] {
    const evens = l.filter((_, index) => index % 2 === 0);
    const odds = l.filter((_, index) => index % 2 !== 0);
    evens.sort((a, b) => a - b);
    const ans: number[] = [];
    for (let i = 0; i < Math.min(evens.length, odds.length); i++) {
        ans.push(evens[i], odds[i]);
    }
    if (evens.length > odds.length) {
        ans.push(evens[evens.length - 1]);
    }
    return ans;
}

function find_closest_elements(numbers: number[]): [number, number] {
    let closest_pair: [number, number] | null = null;
    let distance: number | null = null;

    for (let idx = 0; idx < numbers.length; idx++) {
        const elem = numbers[idx];
        for (let idx2 = 0; idx2 < numbers.length; idx2++) {
            if (idx !== idx2) {
                const elem2 = numbers[idx2];
                const new_distance = Math.abs(elem - elem2);

                if (distance === null || new_distance < distance) {
                    distance = new_distance;
                    closest_pair = [Math.min(elem, elem2), Math.max(elem, elem2)];
                }
            }
        }
    }

    return closest_pair!;
}

