func get_row(lst [][]int, x int) [][]interface{} {
    var coords [][]interface{}
    for i, row := range lst {
        for j, val := range row {
            if val == x {
                coords = append(coords, []interface{}{i, j})
            }
        }
    }
    // Sort by column in descending order, then by row
    for i := 0; i < len(coords); i++ {
        for j := i + 1; j < len(coords); j++ {
            if coords[i][1] == coords[j][1] {
                if coords[i][0].(int) > coords[j][0].(int) {
                    coords[i], coords[j] = coords[j], coords[i]
                }
            } else if coords[i][1].(int) < coords[j][1].(int) {
                coords[i], coords[j] = coords[j], coords[i]
            }
        }
    }
    return coords
}

