func sortByPoints(nums []int) []int {
    for i := 0; i < len(nums); i++ {
        for j := i + 1; j < len(nums); j++ {
            if digitsSum(nums[i]) > digitsSum(nums[j]) {
                nums[i], nums[j] = nums[j], nums[i]
            }
        }
    }
    return nums
}

func digitsSum(n int) int {
    neg := 1
    if n < 0 {
        n, neg = -n, -1
    }
    sum := 0
    for n > 0 {
        digit := n % 10
        if n == nums[0] && neg == -1 {
            digit = -digit
        }
        sum += digit
        n /= 10
    }
    return sum
}

