func circular_shift(x int, shift int) string {
    s := fmt.Sprintf("%d", x)
    if shift > len(s) {
        return reverseString(s)
    } else {
        return s[len(s)-shift:] + s[:len(s)-shift]
    }
}

func reverseString(s string) string {
    runes := []rune(s)
    for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
        runes[i], runes[j] = runes[j], runes[i]
    }
    return string(runes)
}

func pluck(arr []int) []int {
    if len(arr) == 0 {
        return []int{}
    }

    var evens []int
    for _, x := range arr {
        if x%2 == 0 {
            evens = append(evens, x)
        }
    }

    if len(evens) == 0 {
        return []int{}
    }

    minEven := evens[0]
    minIndex := -1
    for i, x := range arr {
        if x == minEven {
            minIndex = i
            break
        }
    }

    return []int{minEven, minIndex}
}

