    if len(word) < 3 {
        return ""
    }
    vowels := map[rune]bool{'a': true, 'e': true, 'i': true, 'o': true, 'u': true, 'A': true, 'E': true, 'O': true, 'U': true, 'I': true}
    for i := len(word) - 2; i > 0; i-- {
        if vowels[rune(word[i])] {
            if !vowels[rune(word[i+1])] && !vowels[rune(word[i-1])] {
                return string(word[i])
            }
        }
    }
    return ""
}

func sort_array(array []int) []int {
    if len(array) == 0 {
        return []int{}
    }
    reverse := (array[0]+array[len(array)-1])%2 == 0
    sortedArray := make([]int, len(array))
    copy(sortedArray, array)
    if reverse {
        for i, j := 0, len(sortedArray)-1; i < j; i, j = i+1, j-1 {
            sortedArray[i], sortedArray[j] = sortedArray[j], sortedArray[i]
        }
    } else {
        for i := 1; i < len(sortedArray); i++ {
            key := sortedArray[i]
            j := i - 1
            for j >= 0 && sortedArray[j] > key {
                sortedArray[j+1] = sortedArray[j]
                j--
            }
            sortedArray[j+1] = key
        }
    }
    return sortedArray
}

