func is_bored(S string) int {
    import (
        "regexp"
    )

    re := regexp.MustCompile(`[.?!]\s*`)
    sentences := re.Split(S, -1)
    count := 0

    for _, sentence := range sentences {
        if len(sentence) >= 2 && sentence[:2] == "I " {
            count++
        }
    }

    return count
}

