public static Pair<Long, Long> evenOddPalindrome(long n) {
    long even_palindrome_count = 0;
    long odd_palindrome_count = 0;
    for (long i = 1; i <= n; i++) {
        if (i % 2 == 1 && isPalindrome(i)) {
            odd_palindrome_count++;
        } else if (i % 2 == 0 && isPalindrome(i)) {
            even_palindrome_count++;
        }
    }
    return Pair.with(even_palindrome_count, odd_palindrome_count);
}

private static boolean isPalindrome(long n) {
    String str = Long.toString(n);
    int len = str.length();
    for (int i = 0; i < len / 2; i++) {
        if (str.charAt(i) != str.charAt(len - 1 - i)) {
            return false;
        }
    }
    return true;
}

public static boolean correctBracketing(String brackets) {
    int depth = 0;
    for (char b : brackets.toCharArray()) {
        if (b == '(') {
            depth += 1;
        } else {
            depth -= 1;
        }
        if (depth < 0) {
            return false;
        }
    }
    return depth == 0;
}

public static long largestPrimeFactor(long n) {
    long largest = 1;
    for (long j = 2; j <= n; j++) {
        if (n % j == 0 && isPrime(j)) {
            largest = Math.max(largest, j);
        }
    }
    return largest;
}

private static boolean isPrime(long k) {
    if (k < 2) {
        return false;
    }
    for (long i = 2; i < k - 1; i++) {
        if (k % i == 0) {
            return false;
        }
    }
    return true;
}

