public static boolean isMultiplyPrime(long a) {
    for (int i = 2; i <= 100; i++) {
        if (!isPrime(i)) {
            continue;
        }
        for (int j = 2; j <= 100; j++) {
            if (!isPrime(j)) {
                continue;
            }
            for (int k = 2; k <= 100; k++) {
                if (!isPrime(k)) {
                    continue;
                }
                if ((long) i * j * k == a) {
                    return true;
                }
            }
        }
    }
    return false;
}

