    coords.sort(Comparator.comparingLong(Pair::getValue1).reversed());
    coords.sort(Comparator.comparingLong(Pair::getValue0));

    return new ArrayList<>(coords);
}

public static ArrayList<Long> tri(long n) {
    if (n == 0) {
        return new ArrayList<>(Arrays.asList(1L));
    }
    ArrayList<Long> myTri = new ArrayList<>(Arrays.asList(1L, 3L));
    for (int i = 2; i <= n; i++) {
        if (i % 2 == 0) {
            myTri.add(i / 2 + 1);
        } else {
            long nextValue = myTri.get(i - 1) + myTri.get(i - 2) + (i + 3) / 2;
            myTri.add(nextValue);
        }
    }
    return myTri;
}

