public static long digits(long n) {
    long product = 1;
    int oddCount = 0;
    String numberStr = Long.toString(n);

    for (char digitChar : numberStr.toCharArray()) {
        int intDigit = Character.getNumericValue(digitChar);
        if (intDigit % 2 == 1) {
            product *= intDigit;
            oddCount++;
        }
    }

    return oddCount == 0 ? 0 : product;
}

