    for (int idx = 0; idx < numbers.size(); idx++) {
        Float elem = numbers.get(idx);
        for (int idx2 = 0; idx2 < numbers.size(); idx2++) {
            if (idx != idx2) {
                Float elem2 = numbers.get(idx2);
                float distance = Math.abs(elem - elem2);
                if (distance < threshold) {
                    return true;
                }
            }
        }
    }
    return false;
}

