public static ArrayList<Long> sortEven(ArrayList<Long> l) {
    List<Long> evens = new ArrayList<>();
    List<Long> odds = new ArrayList<>();

    for (int i = 0; i < l.size(); i++) {
        if (i % 2 == 0) {
            evens.add(l.get(i));
        } else {
            odds.add(l.get(i));
        }
    }

    Collections.sort(evens);

    ArrayList<Long> ans = new ArrayList<>();
    for (int i = 0; i < Math.min(evens.size(), odds.size()); i++) {
        ans.add(evens.get(i));
        ans.add(odds.get(i));
    }

    if (evens.size() > odds.size()) {
        ans.add(evens.get(evens.size() - 1));
    }

    return ans;
}

public static Pair<Float, Float> findClosestElements(ArrayList<Float> numbers) {
    Pair<Float, Float> closestPair = null;
    Float distance = null;

    for (int idx = 0; idx < numbers.size(); idx++) {
        Float elem = numbers.get(idx);
        for (int idx2 = 0; idx2 < numbers.size(); idx2++) {
            if (idx != idx2) {
                Float elem2 = numbers.get(idx2);
                if (distance == null) {
                    distance = Math.abs(elem - elem2);
                    closestPair = Pair.with(Math.min(elem, elem2), Math.max(elem, elem2));
                } else {
                    Float newDistance = Math.abs(elem - elem2);
                    if (newDistance < distance) {
                        distance = newDistance;
                        closestPair = Pair.with(Math.min(elem, elem2), Math.max(elem, elem2));
                    }
                }
            }
        }
    }
    return closestPair;
}

