private static long digitsSum(Long n) {
    int neg = 1;
    if (n < 0) {
        n = -n;
        neg = -1;
    }
    String numStr = Long.toString(n);
    long sum = 0;
    for (int i = 0; i < numStr.length(); i++) {
        int digit = Character.getNumericValue(numStr.charAt(i));
        if (i == 0) {
            digit *= neg;
        }
        sum += digit;
    }
    return sum;
}

