public static long LargestPrimeFactor(long n) {
    long largest = 1;
    for (long j = 2; j <= n; j++) {
        if (n % j == 0 && IsPrime(j)) {
            largest = Math.Max(largest, j);
        }
    }
    return largest;
}

private static bool IsPrime(long k) {
    if (k < 2) {
        return false;
    }
    for (long i = 2; i < k; i++) {
        if (k % i == 0) {
            return false;
        }
    }
    return true;
}

