public static bool IsMultiplyPrime(long a) {
    for (int i = 2; i <= 100; i++) {
        if (!IsPrime(i)) continue;
        for (int j = 2; j <= 100; j++) {
            if (!IsPrime(j)) continue;
            for (int k = 2; k <= 100; k++) {
                if (!IsPrime(k)) continue;
                if ((long)i * j * k == a) return true;
            }
        }
    }
