public static Tuple<float, float> FindClosestElements(List<float> numbers) {
    Tuple<float, float> closestPair = null;
    float? distance = null;

    for (int idx = 0; idx < numbers.Count; idx++) {
        float elem = numbers[idx];
        for (int idx2 = 0; idx2 < numbers.Count; idx2++) {
            if (idx != idx2) {
                float elem2 = numbers[idx2];
                if (!distance.HasValue) {
                    distance = Math.Abs(elem - elem2);
                    closestPair = Tuple.Create(Math.Min(elem, elem2), Math.Max(elem, elem2));
                } else {
                    float newDistance = Math.Abs(elem - elem2);
                    if (newDistance < distance.Value) {
                        distance = newDistance;
                        closestPair = Tuple.Create(Math.Min(elem, elem2), Math.Max(elem, elem2));
                    }
                }
            }
        }
    }

    return closestPair;
}

