        if (str[i] == '[') {
            openingBracketIndex.Add(i);
        } else {
            closingBracketIndex.Add(i);
        }
    }

    closingBracketIndex.Reverse();
    int cnt = 0;
    int i = 0;
    int l = closingBracketIndex.Count;

    foreach (int idx in openingBracketIndex) {
