        .filter_map(|(i, &x)| if i % 2 == 0 { Some(x) } else { None })
        .collect();
    evens.sort_unstable();

    let odds: Vec<isize> = l.iter().enumerate()
        .filter_map(|(i, &x)| if i % 2 != 0 { Some(x) } else { None })
        .collect();

    let mut ans = Vec::with_capacity(l.len());
    for (e, o) in evens.iter().zip(odds.iter()) {
        ans.push(*e);
        ans.push(*o);
    }
    if evens.len() > odds.len() {
        ans.push(evens[evens.len() - 1]);
    }
    ans
}

use std::cmp::Ordering;

fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut closest_pair = (0.0, 0.0);
    let mut distance = None;

    for (idx, &elem) in numbers.iter().enumerate() {
        for (idx2, &elem2) in numbers.iter().enumerate() {
            if idx != idx2 {
                let new_distance = (elem - elem2).abs();
                match distance {
                    None => {
                        distance = Some(new_distance);
                        closest_pair = if elem < elem2 { (elem, elem2) } else { (elem2, elem) };
                    }
                    Some(d) if new_distance < d => {
                        distance = Some(new_distance);
                        closest_pair = if elem < elem2 { (elem, elem2) } else { (elem2, elem) };
                    }
                    _ => {}
                }
            }
        }
    }

    closest_pair
}

