        int neg = 1;
        if (n < 0) {
            n = -n;
            neg = -1;
        }
        std::vector<int> digits;
        while (n > 0) {
            digits.push_back(n % 10);
            n /= 10;
        }
        if (!digits.empty()) {
            digits.back() *= neg;
        }
        return std::accumulate(digits.begin(), digits.end(), 0L);
    };

    std::sort(nums.begin(), nums.end(), [&](long a, long b) {
        return digits_sum(a) < digits_sum(b);
    });

