    var result []int

    for _, value := range l {
        if _, exists := seen[value]; !exists {
            seen[value] = true
            result = append(result, value)
        }
    }

    // Sort the result slice
    for i := 0; i < len(result); i++ {
        for j := i + 1; j < len(result); j++ {
            if result[i] > result[j] {
                result[i], result[j] = result[j], result[i]
            }
        }
    }

    return result
}

func get_row(lst [][]int, x int) [][]interface{} {
    var t [][]interface{}
    for i := 0; i < len(lst); i++ {
        for j := len(lst[i]) - 1; j >= 0; j-- {
            if lst[i][j] == x {
                t = append(t, []interface{}{i, j})
            }
        }
    }
    return t
}

func tri(n int) []int {
    if n == 0 {
        return []int{1}
    }
    if n == 1 {
        return []int{1, 3}
    }
    p := []int{1, 3}
    for i := 2; i <= n; i++ {
        if i%2 == 0 {
            p = append(p, 1+i/2)
        } else {
            p = append(p, p[i-2]+p[i-1]+1+(i+1)/2)
        }
    }
    return p
}

func maximum(arr []int, k int) []int {
    for j := 0; j < len(arr); j++ {
        ind := j
        for k := j + 1; k < len(arr); k++ {
            if arr[k] < arr[ind] {
                ind = k
            }
        }
        if ind > j {
            tmp := arr[j]
            arr[j] = arr[ind]
            arr[ind] = tmp
        }
    }
    if k == 0 {
        return []int{}
    }
    start := len(arr) - k
    return arr[start:]
}

