func sort_even(l []int) []int {
    var even []int
    for index, item := range l {
        if index%2 == 0 {
            even = append(even, item)
        }
    }

    for i := 1; i < len(even); i++ {
        j := i
        for j > 0 && even[j-1] > even[j] {
            even[j], even[j-1] = even[j-1], even[j]
            j--
        }
    }

    result := make([]int, len(l))
    evenIndex := 0
    for index := range l {
        if index%2 == 0 {
            result[index] = even[evenIndex]
            evenIndex++
        } else {
            result[index] = l[index]
        }
    }

    return result
}

func find_closest_elements(numbers []float64) []interface{} {
    var closest_pair []interface{}
    var distance *float64

    for i := 0; i < len(numbers); i++ {
        for j := 0; j < len(numbers); j++ {
            if i != j {
                a, b := numbers[i], numbers[j]
                new_distance := math.Abs(a - b)
                if distance == nil || new_distance < *distance {
                    distance = &new_distance
                    closest_pair = []interface{}{math.Min(a, b), math.Max(a, b)}
                }
            }
        }
    }
    return closest_pair
}

