func order_by_points(nums []int) []int {
    p := nums
    for j := len(p) - 2; j >= 0; j-- {
        for k := 0; k <= j; k++ {
            m, n := sumOfDigits(p[k]), sumOfDigits(p[k+1])
            if m > n {
                p[k], p[k+1] = p[k+1], p[k]
            }
        }
    }
    return p
}

func sumOfDigits(num int) int {
    y, u := 1, 1
    h, d := num, num
    if h < 0 {
        y = -1
        h = -h
    }
    if d < 0 {
        u = -1
        d = -d
    }
    m, n := 0, 0
    for h >= 10 {
        m += h % 10
        h = (h - h%10) / 10
    }
    m += y * h
    for d >= 10 {
        n += d % 10
        d = (d - d%10) / 10
    }
    n += u * d
    return m
}

