    tot := arr[0] + arr[len(arr)-1]
    for j := 0; j < len(arr); j++ {
        ind := j
        for k := j + 1; k < len(arr); k++ {
            if (tot%2 == 1 && arr[k] < arr[ind]) || (tot%2 == 0 && arr[k] > arr[ind]) {
                ind = k
            }
        }
        tmp := arr[j]
        arr[j] = arr[ind]
        arr[ind] = tmp
    }
    return arr
