func fib4(n int) int {
    results := []int{0, 0, 2, 0}
    if n < 4 {
        return results[n]
    }
    for i := 4; i <= n; i++ {
        nextValue := results[len(results)-1] + results[len(results)-2] +
                     results[len(results)-3] + results[0]
        results = append(results[1:], nextValue)
    }
    return results[len(results)-1]
}

