func match_parens(lst []string) string {
    w1 := lst[0] + lst[1]
    y := 0
    u := 1
    for i := 0; i < len(w1); i++ {
        if w1[i] == '(' {
            y++
        } else {
            y--
        }
        if y < 0 {
            u = 0
            break
        }
    }
    if u == 1 && y == 0 {
        return "Yes"
    }
    w1 = lst[1] + lst[0]
    y = 0
    u = 1
    for i := 0; i < len(w1); i++ {
        if w1[i] == '(' {
            y++
        } else {
            y--
        }
        if y < 0 {
            u = 0
            break
        }
    }
    if u == 1 && y == 0 {
        return "Yes"
    }
    return "No"
}

func special_factorial(n int) int {
    p := 1
    t := 1
    for n > 1 {
        y := p
        for y > 0 {
            y--
            t *= n
        }
        p++
        n--
    }
    return t
}

