public static boolean correctBracketing(String brackets) {
    int depth = 0;
    for (char b : brackets.toCharArray()) {
        if (b == '(')
            depth += 1;
        else
            depth -= 1;
        if (depth < 0)
            return false;
    }
    return depth == 0;
}

public static long largestPrimeFactor(long n) {
    return largestPrimeFactorHelper(n, 2);
}

private static long largestPrimeFactorHelper(long n, long factor) {
    if (n < 2) {
        return factor;
    }
    if (n % factor == 0 && isPrime(factor)) {
        return largestPrimeFactorHelper(n / factor, factor);
    } else {
        return largestPrimeFactorHelper(n, factor + 1);
    }
}

private static boolean isPrime(long k) {
    if (k < 2) {
        return false;
    }
    for (long i = 2; i <= Math.sqrt(k); i++) {
        if (k % i == 0) {
            return false;
        }
    }
    return true;
}

