public static ArrayList<Long> tri(long n) {
    if (n == 0) { 
        return new ArrayList<>(Arrays.asList(1L));
    }
    if (n == 1) { 
        return new ArrayList<>(Arrays.asList(1L, 3L));
    }
    ArrayList<Long> p = new ArrayList<>(Arrays.asList(1L, 3L));
    for (long i = 2; i <= n; i++) {
        if (i % 2 == 0) {
            p.add(1 + i / 2);
        } else {
            long nextValue = p.get((int)(i - 2)) + p.get((int)(i - 1)) + 1 + (i + 1) / 2;
            p.add(nextValue);
        }
    }
    return p;
}

public static ArrayList<Long> maximum(ArrayList<Long> arr, long k) {
    for (int j = 0; j < arr.size(); j++) {
        int ind = j;
        for (int l = j + 1; l < arr.size(); l++) {
            if (arr.get(l) < arr.get(ind)) {
                ind = l;
            }
        }
        if (ind > j) {
            long tmp = arr.get(j);
            arr.set(j, arr.get(ind));
            arr.set(ind, tmp);
        }
    }
    if (k == 0) { return new ArrayList<>(); }
    int start = Math.max(0, arr.size() - (int)k);
    return new ArrayList<>(arr.subList(start, arr.size()));
}

public static ArrayList<Long> removeDuplicates(ArrayList<Long> numbers) {
    HashMap<Long, Integer> dict = new HashMap<>();
    for (Long num : numbers) {
        if (dict.containsKey(num)) {
            dict.put(num, dict.get(num) + 1);
        } else {
            dict.put(num, 1);
        }
    }
    return numbers.stream()
                  .filter(x -> dict.get(x) <= 1)
                  .collect(Collectors.toCollection(ArrayList::new));
}

