public static Pair<Float, Float> findClosestElements(ArrayList<Float> numbers) {
    Pair<Float, Float> closest_pair = null;
    float distance = Float.MAX_VALUE;
    for (int i = 0; i < numbers.size(); i++) {
        for (int j = 0; j < numbers.size(); j++) {
            if (i != j) {
                float a = numbers.get(i);
                float b = numbers.get(j);
                if (distance == Float.MAX_VALUE) {
                    distance = Math.abs(a - b);
                    closest_pair = Pair.with(Math.min(a, b), Math.max(a, b));
                } else {
                    float new_distance = Math.abs(a - b);
                    if (new_distance < distance) {
                        distance = new_distance;
                        closest_pair = Pair.with(Math.min(a, b), Math.max(a, b));
                    }
                }
            }
        }
    }
    return closest_pair;
}

