public static boolean isNested(String string) {
    List<Integer> opening_bracket_index = new ArrayList<>();
    List<Integer> closing_bracket_index1 = new ArrayList<>();

    for (int i = 0; i < string.length(); i++) {
        if (string.charAt(i) == '[') {
            opening_bracket_index.add(i);
        } else {
            closing_bracket_index1.add(i);
        }
    }

    List<Integer> closing_bracket_index = new ArrayList<>();
    for (int i = 0; i < closing_bracket_index1.size(); i++) {
        closing_bracket_index.add(closing_bracket_index1.get(closing_bracket_index1.size() - i - 1));
    }

    int cnt = 0;
    int i = 0;
    int l = closing_bracket_index.size();
    for (int k = 0; k < opening_bracket_index.size(); k++) {
        if (i < l && opening_bracket_index.get(k) < closing_bracket_index.get(i)) {
            cnt += 1;
            i += 1;
        }
    }

