    Tuple<float, float> closest_pair = null;
    float distance = 0;

    for (int i = 0; i < numbers.Count; i++) {
        for (int j = 0; j < numbers.Count; j++) {
            if (i != j) {
                float a = numbers[i], b = numbers[j];
                if (closest_pair == null) {
                    distance = Math.Abs(a - b);
                    closest_pair = Tuple.Create(Math.Min(a, b), Math.Max(a, b));
                } else {
                    float new_distance = Math.Abs(a - b);
                    if (new_distance < distance) {
                        distance = new_distance;
                        closest_pair = Tuple.Create(Math.Min(a, b), Math.Max(a, b));
                    }
                }
            }
        }
    }
    return closest_pair;
}

