            closing_bracket_index1.push(i);
        }
    }

    let mut closing_bracket_index = Vec::new();
    for i in (0..closing_bracket_index1.len()).rev() {
        closing_bracket_index.push(closing_bracket_index1[i]);
    }

    let mut cnt = 0;
    let mut i = 0;
    let l = closing_bracket_index.len();

    for k in 0..opening_bracket_index.len() {
        if i < l && opening_bracket_index[k] < closing_bracket_index[i] {
