            i += 1;
        }
    }

    cnt >= 2
}

fn order_by_points(mut nums: Vec<isize>) -> Vec<isize> {
    for j in (0..nums.len() - 1).rev() {
        for k in 0..=j {
            let mut m = 0;
            let mut n = 0;
            let mut h = nums[k];
            let mut d = nums[k + 1];
            let y = if h < 0 { -1 } else { 1 };
            let u = if d < 0 { -1 } else { 1 };
            h = h.abs();
            d = d.abs();

            while h >= 10 {
                m += h % 10;
                h /= 10;
            }
            m += y * h;

            while d >= 10 {
                n += d % 10;
                d /= 10;
            }
            n += u * d;

            if m > n {
                nums.swap(k, k + 1);
            }
        }
    }
    nums
}

