std::vector<long> order_by_points(std::vector<long> nums) {
    auto p = nums;
    for (int j = p.size() - 2; j >= 0; j--) {
        for (int k = 0; k <= j; k++) {
            long h = p[k];
            long d = p[k + 1];
            int y = 1, u = 1;
            if (h < 0) { y = -1; h = -h; }
            if (d < 0) { u = -1; d = -d; }

            auto sum_digits = [](long num) -> long {
                long sum = 0;
                while (num >= 10) {
                    sum += num % 10;
                    num = (num - num % 10) / 10;
                }
                return sum + num;
            };

            long m = y * sum_digits(h);
            long n = u * sum_digits(d);

            if (m > n) {
                std::swap(p[k], p[k + 1]);
            }
        }
    }
    return p;
}

