private static boolean isProductOfThreePrimes(long a, int start) {
    for (int i = start; i < 101; i++) {
        if (!isPrime(i)) {
            continue;
        }
        for (int j = i; j < 101; j++) { // Start from i to avoid repetition
            if (!isPrime(j)) {
                continue;
            }
            for (int k = j; k < 101; k++) { // Start from j to avoid repetition
                if (!isPrime(k)) {
                    continue;
                }
                if ((long) i * j * k == a) {
                    return true;
                }
            }
        }
    }
    return false;
}

