            neg = -1;
        }
        int sum = 0;
        foreach (char c in n.ToString()) {
            if (c == '-') continue;
            sum += (int)(c - '0') * (c == n.ToString()[0] ? neg : 1);
        }
        return sum;
    };

    nums.Sort((a, b) => digits_sum(a).CompareTo(digits_sum(b)));
    return nums;
}

