fn pluck(arr: Vec<isize>) -> Vec<isize> {
    let mut result = Vec::new();
    if arr.is_empty() {
        return result;
    }
    let mut evens = Vec::new();
    let mut min = isize::MAX;
    let mut min_index = 0;
    for (i, &x) in arr.iter().enumerate() {
        if x % 2 == 0 {
            evens.push(x);
            if x < min {
                min = x;
                min_index = i as isize;
            }
        }
    }
    if evens.is_empty() {
        return result;
    }
    result.push(min);
    result.push(min_index);
    result
}

