        for (long i = 2; i <= std::sqrt(n); ++i) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    };

    long largest = 1;
    for (long j = 2; j < n + 1; ++j) {
        if (n % j == 0 && isPrime(j)) {
            if (j > largest) {
                largest = j;
            }
        }
    }
    return largest;
}

