std::vector<long> order_by_points(std::vector<long> nums) {
    auto digits_sum = [](long n) -> int {
        int neg = 1;
        if (n < 0) {
            n = -n;
            neg = -1;
        }
        int sum = 0;
        std::string num_str = std::to_string(n);
        for (size_t i = 0; i < num_str.size(); ++i) {
            if (i == 0) {
                sum += (num_str[i] - '0') * neg;
            } else {
                sum += (num_str[i] - '0');
            }
        }
        return sum;
    };

    std::stable_sort(nums.begin(), nums.end(), [&](long a, long b) {
        return digits_sum(a) < digits_sum(b);
    });

    return nums;
}

