    var closestPair: (Double, Double) = (0.0, 0.0)

    for (idx, elem) in numbers.enumerated() {
        for (idx2, elem2) in numbers.enumerated() {
            if idx != idx2 {
                let newDistance = abs(elem - elem2)
                if newDistance < distance {
