extension NSRegularExpression {
    func split(input: String, atRange range: NSRange) -> [String] {
        let matches = self.matches(in: input, options: [], range: range)
        var sentences: [String] = []
        var lastEndIndex = range.location

        for match in matches {
            if lastEndIndex < match.range.location {
                let startIndex = input.index(input.startIndex, offsetBy: lastEndIndex)
                let endIndex = input.index(input.startIndex, offsetBy: match.range.location)
                sentences.append(String(input[startIndex..<endIndex]))
            }
            lastEndIndex = NSMaxRange(match.range)
        }

        if lastEndIndex < range.upperBound {
            let startIndex = input.index(input.startIndex, offsetBy: lastEndIndex)
            sentences.append(String(input[startIndex..<input.endIndex]))
        }

        return sentences
    }
}

