function is_multiply_prime(a: number): boolean {
    class IsPrime {
        static is_prime(n: number): boolean {
            for (let j = 2; j < n; j++) {
                if (n % j === 0) {
                    return false;
                }
            }
            return true;
        }
    }

    for (let i = 2; i < 101; i++) {
        if (!IsPrime.is_prime(i)) {
            continue;
        }
        for (let j = i; j < 101; j++) {
            if (!IsPrime.is_prime(j)) {
                continue;
            }
            for (let k = j; k < 101; k++) {
                if (!IsPrime.is_prime(k)) {
                    continue;
                }
                if (i * j * k === a) {
                    return true;
                }
            }
        }
    }
    return false;
}

