function tri(n: number): number[] {
    if (n === 0) {
        return [1];
    }
    const my_tri: number[] = [1, 3];
    for (let i = 2; i <= n; i++) {
        if (i % 2 === 0) {
            my_tri.push(i / 2 + 1);
        } else {
            my_tri.push(my_tri[my_tri.length - 1] + my_tri[my_tri.length - 2] + Math.floor((i + 3) / 2));
        }
    }
    return my_tri;
}

