function find_closest_elements(numbers: number[]): [number, number] {
    let closest_pair: [number, number] = [numbers[0], numbers[1]];
    let distance = Math.abs(numbers[1] - numbers[0]);

    for (let i = 0; i < numbers.length; i++) {
        for (let j = i + 1; j < numbers.length; j++) {
            if (Math.abs(numbers[i] - numbers[j]) < distance) {
                closest_pair = [numbers[i], numbers[j]];
                distance = Math.abs(numbers[i] - numbers[j]);
            }
        }
    }

    closest_pair.sort((a, b) => a - b);
    return closest_pair;
}

