function circular_shift(x: number, shift: number): string {
    const s = x.toString();
    if (shift > s.length) {
        return s.split('').reverse().join('');
    } else {
        return s.slice(-shift) + s.slice(0, -shift);
    }
}

function pluck(arr: number[]): number[] {
    const result: number[] = [];
    if (arr.length === 0) {
        return result;
    }
    let min = Number.MAX_SAFE_INTEGER;
    let minIndex = -1;
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] % 2 === 0) {
            if (arr[i] < min) {
                min = arr[i];
                minIndex = i;
            }
        }
    }
    if (minIndex !== -1) {
        result.push(min);
        result.push(minIndex);
    }
    return result;
}

function modp(n: number, p: number): number {
    let ret = 1;
    for (let i = 0; i < n; i++) {
        ret = (ret * 2) % p;
