function fib4(n: number): number {
    const results: number[] = [0, 0, 2, 0];
    if (n < 4) {
        return results[n];
    }

    for (let i = 4; i <= n; i++) {
        results.push(results[0] + results[1] + results[2] + results[3]);
        results.shift();
    }
    return results[3];
}

