    for (const s of S) {
        let val = 0;
        for (const i of s) {
            if (i === '(') {
                val += 1;
            } else {
                val -= 1;
            }
            if (val < 0) {
                break;
            }
        }
        if (val === 0) {
            return "Yes";
        }
    }
    return "No";
}

