    closest_pair[1] = numbers[1]
    distance := math.Abs(numbers[1] - numbers[0])

    for i := 0; i < len(numbers); i++ {
        for j := i + 1; j < len(numbers); j++ {
            if math.Abs(numbers[i]-numbers[j]) < distance {
                closest_pair[0] = numbers[i]
                closest_pair[1] = numbers[j]
                distance = math.Abs(numbers[i] - numbers[j])
            }
        }
    }

    sort.Slice(closest_pair, func(i, j int) bool {
        return closest_pair[i].(float64) < closest_pair[j].(float64)
    })

    return closest_pair
}

