func is_nested(myString string) bool {
    var opening_bracket_index []int
    var closing_bracket_index []int

    for i, char := range myString {
        if char == '[' {
            opening_bracket_index = append(opening_bracket_index, i)
        } else {
            closing_bracket_index = append(closing_bracket_index, i)
        }
    }

    // Reverse the closing_bracket_index slice
    for i, j := 0, len(closing_bracket_index)-1; i < j; i, j = i+1, j-1 {
        closing_bracket_index[i], closing_bracket_index[j] = closing_bracket_index[j], closing_bracket_index[i]
    }

    i, l := 0, len(closing_bracket_index)
    for _, idx := range opening_bracket_index {
        if i < l && idx < closing_bracket_index[i] {
            i += 1
        }
    }
    return i >= 2
}

func order_by_points(nums []int) []int {
    result := make([]int, len(nums))
    copy(result, nums)

    sort.Slice(result, func(i, j int) bool {
        sum1 := digitSum(result[i])
        sum2 := digitSum(result[j])

        return sum1 < sum2
    })

    return result
}

func digitSum(num int) int {
    sum := 0
    strNum := fmt.Sprintf("%d", num)
    for i, char := range strNum {
        if i != 0 || num >= 0 {
            sum += int(char - '0')
            if i == 1 && num < 0 {
                sum = -sum
            }
        }
    }
    return sum
}

