    if shift > len(s) {
        return reverseString(s)
    } else {
        return s[len(s)-shift:] + s[:len(s)-shift]
    }
}

func reverseString(s string) string {
    runes := []rune(s)
    for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
        runes[i], runes[j] = runes[j], runes[i]
    }
    return string(runes)
}

func pluck(arr []int) []int {
    result := []int{}
    if len(arr) == 0 {
        return result
    }
    min := int(^uint(0) >> 1)
    minIndex := -1
    for i, num := range arr {
        if num%2 == 0 {
            if num < min {
                min = num
                minIndex = i
            }
        }
    }
    if minIndex != -1 {
        result = append(result, min, minIndex)
    }
    return result
}

func modp(n int, p int) int {
    ret := 1
    for i := 0; i < n; i++ {
        ret = (ret * 2) % p
    }
    return ret
}

