}

public static long LargestPrimeFactor(long n) {
    long largest = 1;
    for (long j = 2; j <= n; j++) {
        if (n % j == 0) {
            bool is_prime = j >= 2;
            for (long i = 2; i < j - 1; i++) {
                if (j % i == 0) {
                    is_prime = false;
                    break;
                }
            }
            if (is_prime) {
                largest = Math.Max(largest, j);
            }
        }
    }
    return largest;
}

