public static bool IsMultiplyPrime(long a) {
    for (int i = 2; i < 101; i++) {
        if (!IsPrime(i)) {
            continue;
        }
        for (int j = i; j < 101; j++) {
            if (!IsPrime(j)) {
                continue;
            }
            for (int k = j; k < 101; k++) {
                if (!IsPrime(k)) {
                    continue;
                }
                if ((long)i * j * k == a) {
                    return true;
                }
            }
        }
    }
    return false;
}

