public static List<long> Tri(long n) {
    if (n == 0) {
        return new List<long> { 1 };
    }
    List<long> my_tri = new List<long> { 1, 3 };
    for (long i = 2; i <= n; i++) {
        if (i % 2 == 0) {
            my_tri.Add(i / 2 + 1);
        } else {
            my_tri.Add(my_tri[my_tri.Count - 1] + my_tri[my_tri.Count - 2] + (i + 3) / 2);
        }
    }
    return my_tri;
}

