public static Tuple<float, float> FindClosestElements(List<float> numbers) {
    List<float> closest_pair = new List<float>();
    closest_pair.Add(numbers[0]);
    closest_pair.Add(numbers[1]);
    float distance = Math.Abs(numbers[1] - numbers[0]);
    for (int i = 0; i < numbers.Count; i++) {
        for (int j = i + 1; j < numbers.Count; j++) {
            if (Math.Abs(numbers[i] - numbers[j]) < distance) {
                closest_pair.Clear();
                closest_pair.Add(numbers[i]);
                closest_pair.Add(numbers[j]);
                distance = Math.Abs(numbers[i] - numbers[j]);
            }
        }
    }
    closest_pair.Sort();
    return Tuple.Create(closest_pair[0], closest_pair[1]);
}

