public static bool IsNested(string str) {
    List<int> opening_bracket_index = new List<int>(), closing_bracket_index = new List<int>();
    for (int i = 0; i < str.Length; i++) {
        if (str[i] == '[') {
            opening_bracket_index.Add(i);
        } else {
            closing_bracket_index.Add(i);
        }
    }
    closing_bracket_index.Reverse();
    int i = 0, l = closing_bracket_index.Count;
    foreach (int idx in opening_bracket_index) {
        if (i < l && idx < closing_bracket_index[i]) {
            i += 1;
        }
    }
    return i >= 2;
}

public static List<long> OrderByPoints(List<long> nums) {
    var result = new List<long>(nums);
    result.Sort((o1, o2) => {
        int sum1 = 0;
        int sum2 = 0;

        for (int i = 0; i < Math.Abs(o1).ToString().Length; i++) {
            if (i != 0 || o1 >= 0) {
                sum1 += (Math.Abs(o1).ToString()[i] - '0');
                if (i == 1 && o1 < 0) {
                    sum1 = -sum1;
                }
            }
        }
        for (int i = 0; i < Math.Abs(o2).ToString().Length; i++) {
            if (i != 0 || o2 >= 0) {
                sum2 += (Math.Abs(o2).ToString()[i] - '0');
                if (i == 1 && o2 < 0) {
                    sum2 = -sum2;
                }
            }
        }
        return sum1.CompareTo(sum2);
    });
    return result;
}

