public static string CircularShift(long x, long shift) {
    string s = x.ToString();
    if (shift > s.Length) {
        return new string(s.Reverse().ToArray());
    } else {
        int actualShift = (int)(shift % s.Length);
        return s.Substring(s.Length - actualShift) + s.Substring(0, s.Length - actualShift);
    }
}

