fn even_odd_palindrome(n: isize) -> (isize, isize) {
    let mut even_palindrome_count = 0;
    let mut odd_palindrome_count = 0;

    for i in 1..=n {
        if is_palindrome(i) {
            if i % 2 == 1 {
                odd_palindrome_count += 1;
            } else {
                even_palindrome_count += 1;
            }
        }
    }

    (even_palindrome_count, odd_palindrome_count)
}

fn is_palindrome(mut num: isize) -> bool {
    let original = num;
    let mut reversed = 0;

    while num > 0 {
        reversed = reversed * 10 + num % 10;
        num /= 10;
    }

    original == reversed
}

fn correct_bracketing(brackets: String) -> bool {
    let mut depth = 0;
    for b in brackets.chars() {
        if b == '(' {
            depth += 1;
        } else {
            depth -= 1;
        }
        if depth < 0 {
            return false;
        }
    }
    depth == 0
}

