    sorted_arr.sort_by_key(|&x| Reverse(x));
    sorted_arr
        .into_iter()
        .filter_map(|var| match var {
            1 => Some("One".to_string()),
            2 => Some("Two".to_string()),
            3 => Some("Three".to_string()),
            4 => Some("Four".to_string()),
            5 => Some("Five".to_string()),
