fn unique(l: Vec<isize>) -> Vec<isize> {
    let mut result: HashSet<isize> = l.into_iter().collect();
    let mut result_vec: Vec<isize> = result.drain().collect();
    result_vec.sort();
    result_vec
}

fn get_row(lst: Vec<Vec<isize>>, x: isize) -> Vec<(isize, isize)> {
    let mut coords = Vec::new();
    for (i, row) in lst.iter().enumerate() {
        for (j, &val) in row.iter().rev().enumerate() {
            if val == x {
                coords.push((i as isize, (row.len() - 1 - j) as isize));
            }
        }
    }
    coords
}

fn tri(n: isize) -> Vec<isize> {
    if n == 0 {
        return vec![1];
    }
    let mut my_tri = vec![1, 3];
    for i in 2..=n {
        if i % 2 == 0 {
            my_tri.push(i / 2 + 1);
        } else {
            let last = my_tri[my_tri.len() - 1];
            let second_last = my_tri[my_tri.len() - 2];
            my_tri.push(last + second_last + (i + 3) / 2);
        }
    }
    my_tri
}

