use std::collections::HashMap;

fn remove_duplicates(numbers: Vec<isize>) -> Vec<isize> {
    let mut count = HashMap::new();
    for &number in &numbers {
        *count.entry(number).or_insert(0) += 1;
    }
    numbers.into_iter().filter(|&n| count[&n] == 1).collect()
}

