fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    if numbers.len() < 2 {
        panic!("The list must contain at least two elements.");
    }

    let mut closest_pair = (numbers[0], numbers[1]);
    let mut distance = (numbers[1] - numbers[0]).abs();

    for i in 0..numbers.len() {
        for j in i + 1..numbers.len() {
            let current_distance = (numbers[i] - numbers[j]).abs();
            if current_distance < distance {
                closest_pair = (numbers[i], numbers[j]);
                distance = current_distance;
            }
        }
    }

    match closest_pair.0.partial_cmp(&closest_pair.1) {
        Some(Ordering::Less) => closest_pair,
        _ => (closest_pair.1, closest_pair.0),
    }
}

