    public:
        static bool is_prime(int n) {
            for (int j = 2; j < n; j++) {
                if (n % j == 0) {
                    return false;
                }
            }
            return true;
        }
    };
    for (int i = 2; i < 101; i++) {
        if (!IsPrime::is_prime(i)) {
            continue;
        }
        for (int j = i; j < 101; j++) {
            if (!IsPrime::is_prime(j)) {
                continue;
            }
            for (int k = j; k < 101; k++) {
                if (!IsPrime::is_prime(k)) {
