        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }

    if (n == 0 || n == 1) {
        return 0;
    } else if (n == 2) {
        return 2;
    } else if (n == 3) {
        return 0;
    }

    long[] f = new long[(int) n + 1];
    f[0] = 0;
    f[1] = 0;
    f[2] = 2;
    f[3] = 0;

    for (int i = 4; i <= n; i++) {
