func split_words(txt: String) -> Result<[String], Int> {
    if txt.contains(" ") {
        var out: [String] = []
        var current = ""
        for char in txt + " " {
            if char == " " {
                if !current.isEmpty {
                    out.append(current)
                }
                current = ""
            } else {
                current.append(char)
            }
        }
        return .success(out)
    }

    if txt.contains(",") {
        var out: [String] = []
        var current = ""
        for char in txt + "," {
            if char == "," {
                if !current.isEmpty {
                    out.append(current)
                }
                current = ""
            } else {
                current.append(char)
            }
        }
        return .success(out)
    }

    let num = txt.filter { $0.isLowercase && Int($0.asciiValue ?? 0) % 2 == 0 }.count
    return .failure(num)
}

